    "settings.notes.guide.editing": "選擇“格式化編號”時，單擊編號或把光標移到編號處，即可展開並編輯原始標記。",
    "settings.notes.guide.safety": "編號只用於顯示，不會改寫 Markdown ID 或定義。",
    "settings.noteOverrides.guide.title": "目前筆記屬性（Properties）是可選的",
    "settings.noteOverrides.guide.intro": "大多數筆記都不需要添加 Number Suite 屬性；全局預設設定會自動生效。",
    "settings.noteOverrides.guide.action": "只有某篇筆記需要不同設定時，才開啟側邊欄的「目前筆記」。改回「跟隨全域」會移除該筆記的個別設定。舊版 Number Suite 屬性只會在你明確修改時轉換，其他屬性不變。",
    "settings.scheme": "編號方案",
    "settings.scheme.desc": "這套方案用於畫面顯示，也用於之後的寫入操作。切換介面語言不會自動更換編號方案。",
    "settings.missing": "跳級標題如何編號",
    "settings.missing.desc": "例如二級標題後直接出現四級標題、缺少三級標題時：可用該級的起始數字補齊、只顯示四級序號，或跳過編號並提示。僅調整顯示不會改動筆記。",
    "settings.write": "檔案操作",
    "settings.markers": "寫入 Number Suite 隱形標記",
    "settings.markers.desc": "實驗功能：隱形標記能讓 Number Suite 準確識別自己寫入的序號，但可能影響其他工具和標題連結；預設為關閉。",
    "settings.cleanup": "操作識別範圍預設值",
    "settings.cleanup.desc": "選擇清理和重編號預覽最初顯示的識別範圍；每次操作都可臨時更改，不會把該選擇寫入筆記。",
    "settings.multiple": "清理標題開頭的多組已識別序號",
    "settings.multiple.desc": "例如標題開頭疊加了兩組能識別的編號，可在預覽確認後一起清理；無法確認的文字仍會保留。",
    "settings.normalize": "重新編號時調整明確識別的手寫序號",
    "settings.normalize.desc": "重新編號時，也替換插件能可靠識別的手寫標題序號。實際更改會先顯示在預覽中，請確認後再應用。",
    "settings.operations.guide.title": "如何執行檔案操作",
    "settings.operations.guide.intro": "這裡用於設定規則；實際操作從側欄的“目前筆記”選項卡或命令面板啟動。",
    "settings.operations.guide.step.open": "以編輯模式打開一篇 Markdown 筆記，然後選擇 Number Suite 側欄中的“目前筆記”，或運行“打開目前筆記控制面板”。",
    "settings.operations.guide.step.choose": "選擇寫入序號、清理序號、重新編號或移除 Number Suite 隱形標記；也可以直接從命令面板運行對應的目前筆記命令。",
    "settings.operations.guide.step.preview": "逐項檢查修改前後內容和警告，再選擇“應用變更”；關閉或取消預覽不會寫入任何內容。",
    "settings.operations.guide.operations": "寫入會補齊缺失序號；清理會刪除可安全識別的序號；重新編號會按目前方案替換高置信度編號；移除隱形標記會保留可見序號，只刪除 Number Suite 標記。",
    "settings.operations.guide.safety": "寫入、移除或重新編號會改變標題文字，可能使指向標題的連結或嵌入失效。請先檢查預覽；外掛不會自動修改這些連結。",
