    "settings.headings.guide.virtual": "'가상 번호 표시'는 선택한 형식으로 계산한 번호를 보여 줍니다.",
    "settings.headings.guide.conceal": "'저장된 번호 숨기기'는 확실하게 인식된 번호만 숨기며 삭제하지 않습니다.",
    "settings.headings.guide.together": "두 옵션을 켜면 기존 번호를 화면에서 숨기고 선택한 형식의 번호를 대신 표시합니다. Markdown은 그대로입니다.",
    "settings.headings.guide.views": "번호를 표시할 화면은 '표시 및 일괄 처리'에서 선택합니다. 소스 모드는 기본적으로 원본 Markdown을 보여 줍니다.",
    "settings.headings.guide.write": "번호를 Markdown에 직접 저장하려면 '쓰기 및 정리'에서 미리 보기와 함께 파일 작업을 실행하세요.",
    "settings.captions": "캡션 번호",
    "settings.captions.enable": "가상 캡션 번호 표시",
    "settings.captions.enable.desc": "인식된 각 캡션에 화면 표시용 번호를 붙입니다. Figure, Table, Equation, Code는 각 Markdown 파일에서 각각 1부터 시작합니다.",
    "settings.captions.placement": "화면 표시 위치",
