    "settings.captions.imageTooltip.desc": "독립 이미지나 연결된 Figure 캡션 위에 커서를 올리면 캡션과 의미 있는 대체 텍스트를 보여 줍니다. 인라인 이미지나 표 셀 안의 이미지는 대체 텍스트만 표시할 수 있습니다.",
    "settings.captions.alignment": "캡션 정렬",
    "settings.captions.alignment.desc": "캡션 종류별로 가운데 정렬을 지정합니다. 끄면 현재 Obsidian 테마를 따릅니다.",
    "settings.captions.center.figure": "그림 캡션 가운데 정렬",
    "settings.captions.center.table": "표 캡션 가운데 정렬",
    "settings.captions.center.equation": "수식 캡션 가운데 정렬",
    "settings.captions.center.code": "코드 캡션 가운데 정렬",
    "settings.captions.guide.title": "캡션은 한 번만 작성하면 표시 방식은 Number Suite가 처리합니다",
    "settings.captions.guide.intro": "이미지, 표, 수식 또는 코드 블록 위에 Figure: 개요와 같은 캡션 줄을 입력하세요. Number Suite는 원본 줄을 바꾸지 않고 캡션으로 표시합니다.",
    "settings.captions.guide.example.title": "Markdown → 캡션 표시",
    "settings.captions.guide.example.source": "Figure: 시스템 구성\n\n![[architecture.png]]\n\n\nTable: 결과\n\n| 항목 | 값 |\n| --- | --- |",
    "settings.captions.guide.example.result": "그림 캡션은 이미지에, 표 캡션은 표에 연결됩니다. 두 그룹 사이에 빈 줄 두 개를 두면 잘못 연결되지 않습니다.",
    "settings.captions.guide.example.preview.figure": "Figure 1: 시스템 구성",
    "settings.captions.guide.example.preview.table": "Table 1: 결과",
