    "settings.captions.guide.counter": "종류별로 번호를 따로 매기며 Markdown 파일마다 1부터 다시 시작합니다.",
    "settings.captions.guide.binding": "캡션은 인접한 이미지, 표, 수식, 코드 블록에 연결할 수 있습니다. 사이에 빈 줄은 최대 한 줄만 허용됩니다. 빈 줄 두 개는 연결을 끊으며, 가능한 대상이 여러 개면 플러그인이 임의로 선택하지 않습니다.",
    "settings.captions.guide.safety": "캡션의 모습, 번호, 정렬, 표시 위치는 화면만 바꿉니다. 저장된 캡션 줄은 그대로입니다.",
    "settings.captions.guide.placement": "캡션 종류별로 대상 위 또는 아래를 선택할 수 있습니다. 연결된 캡션은 테마와 무관하게 대상 근처에 표시됩니다.",
    "settings.captions.guide.hover": "이미지 또는 Figure 캡션 위에 커서를 올리면 캡션과 유용한 대체 텍스트가 나옵니다. 중복 문구와 크기 정보만 있는 값은 제외됩니다.",
    "settings.captions.guide.editing": "캡션 표시 영역에 커서를 두면 원래 위치의 Markdown을 편집할 수 있습니다. 소스 모드에서는 항상 원본이 표시됩니다.",
    "settings.captions.guide.blockId": "독립 Figure, Table, Equation, Code 대상은 마우스 오른쪽 버튼으로 캡션을 만들 수 있습니다. 블록 ID는 만들지 않습니다.",
    "settings.captions.guide.reference": "이름이 유일한 캡션은 @[[#Figure: 시스템 구성]]처럼 전체 이름으로 바로 참조할 수 있습니다.",
    "settings.references": "같은 노트 내 상호 참조",
