    "settings.references.guide.intro": "이 노트의 제목이나 캡션 링크 앞에 @를 붙이세요. 예: @[[#설치]]. Number Suite가 클릭 가능한 참조 레이블을 보여 줍니다. 일반 [[#...]] 링크는 변경되지 않습니다.",
