    "settings.references.guide.caption.source": "Figure: 시스템 구성\n자세한 내용은 @[[#Figure: 시스템 구성]] 참고",
    "settings.references.guide.caption.result": "캡션 번호가 있으면 'Figure 1: 시스템 구성', 없으면 'Figure: 시스템 구성'으로 표시됩니다.",
    "settings.references.guide.caption.preview": "Figure 1: 시스템 구성",
    "settings.references.guide.methods.title": "링크 방식 선택",
    "settings.references.guide.methods.manual": "제목은 @[[#제목]], 캡션은 @[[#Figure: 시스템 구성]] 형식으로 입력하세요. 대상 이름이 유일하면 블록 ID가 필요하지 않습니다.",
    "settings.references.guide.methods.copy": "제목이나 캡션을 마우스 오른쪽 버튼으로 누르고 '상호 참조 복사'를 선택하세요. 기존 블록 ID를 재사용하고, 없는 경우에는 새 ID를 쓰기 전에 미리 보기와 확인을 거칩니다.",
    "settings.references.guide.methods.captionId": "캡션을 만든다고 ID가 자동으로 만들어지지 않습니다. '상호 참조 복사'를 직접 실행했을 때만 새 ID가 생길 수 있습니다.",
    "settings.references.guide.requirements.title": "참조 대상 인식 규칙",
