    "settings.references.guide.unchanged.title": "변경되지 않는 항목",
    "settings.references.guide.unchanged.body": "일반 [[#...]] 링크나 다른 노트의 링크는 그대로입니다. 대상을 찾을 수 없거나 이름이 중복되면 참조 레이블로 바꾸지 않고 기존 링크도 자동으로 다시 쓰지 않습니다.",
    "settings.notes": "각주 및 미주 번호",
