    "settings.notes.enable.desc": "각주는 1, 2, 3으로, 미주는 E1, E2, E3으로 표시합니다. 두 번호 모두 파일마다 1부터 다시 시작합니다. 정의가 없거나 중복 또는 충돌하면 변경하지 않습니다.",
    "settings.notes.display": "라이브 미리 보기 표시",
