    "settings.notes.guide.intro": "각주에는 일반 Obsidian 각주 문법을, 미주에는 ID 앞에 endnote:를 사용합니다. 번호는 별도로 매깁니다.",
    "settings.notes.guide.footnote.title": "각주",
