    "settings.notes.guide.editing": "'정리된 번호'를 선택했다면 번호를 클릭하거나 커서를 옮겨 원본 표시를 보고 편집할 수 있습니다.",
    "settings.notes.guide.safety": "번호는 화면에만 적용됩니다. Markdown ID와 정의는 수정하지 않습니다.",
    "settings.noteOverrides.guide.title": "현재 노트의 Properties는 선택 사항",
    "settings.noteOverrides.guide.intro": "대부분의 노트에는 Number Suite Properties가 필요하지 않습니다. 플러그인 전체 설정이 자동으로 적용됩니다.",
    "settings.noteOverrides.guide.action": "노트마다 다른 설정이 필요할 때만 '현재 노트'를 여세요. '전체 설정 따르기'를 선택하면 해당 개별 설정이 제거됩니다. 이전 Number Suite 필드는 직접 수정할 때만 변환되며 다른 Properties는 그대로입니다.",
    "settings.missing": "제목 단계를 건너뛴 경우",
    "settings.missing.desc": "H2 다음에 H3 없이 H4가 나오면 누락된 단계의 시작 번호를 채우거나, H4 번호만 표시하거나, 번호를 생략하고 경고할 수 있습니다. 별도로 파일 작업을 실행해야 Markdown이 바뀝니다.",
    "settings.write": "파일 작업",
    "settings.markers": "Number Suite 숨김 표시 쓰기",
    "settings.markers.desc": "실험 기능입니다. 숨김 표시로 플러그인이 작성한 번호를 정확히 인식할 수 있지만 다른 도구나 제목 링크에 영향을 줄 수 있습니다. 기본적으로 꺼져 있습니다.",
    "settings.cleanup": "파일 작업 기본 인식 범위",
    "settings.cleanup.desc": "삭제와 다시 매기기 미리 보기에서 처음 보여 줄 인식 범위를 정합니다. 작업마다 변경할 수 있으며 해당 선택을 노트에 쓰지 않습니다.",
    "settings.multiple": "연속된 인식 번호 제거",
    "settings.multiple.desc": "제목 앞에 인식할 수 있는 번호가 여러 개 있으면 미리 보기 확인 후 함께 제거할 수 있습니다. 애매한 텍스트는 보호합니다.",
    "settings.normalize": "번호를 다시 매길 때 확실한 수동 번호도 정리",
    "settings.normalize.desc": "다시 매길 때 플러그인이 높은 확신도로 인식한 수동 제목 번호도 선택한 형식으로 바꿉니다. 적용 전 미리 보기를 확인하세요.",
    "settings.operations.guide.title": "파일 작업 사용 방법",
