    "settings.references.guide.caption.preview": "Figure 1: Architecture du système",
    "settings.references.guide.methods.title": "Choisir la forme du lien",
    "settings.references.guide.methods.manual": "Utilisez @[[#Titre]] pour un titre ou @[[#Figure: Architecture du système]] pour une légende. Si le nom de la cible est unique, aucun identifiant de bloc n’est nécessaire.",
    "settings.references.guide.methods.copy": "Faites un clic droit sur un titre ou une légende et choisissez « Copier le renvoi ». Un identifiant existant est réutilisé ; sinon, vous devez examiner et confirmer le nouvel identifiant avant qu’il soit écrit.",
    "settings.references.guide.methods.captionId": "Créer une légende ne crée pas d’identifiant. Seule l’action explicite « Copier le renvoi » peut en ajouter un.",
    "settings.references.guide.requirements.title": "Règles de recherche des cibles",
    "settings.references.guide.requirements.heading": "Les titres et légendes partagent le même espace de recherche dans cette note. La cible demandée doit être unique.",
    "settings.references.guide.requirements.caption": "Un lien vers une légende doit comporter son type fixe, par exemple Figure: ou Table:. Sans type, seuls les titres sont recherchés.",
    "settings.references.guide.requirements.sameFile": "Le renvoi et sa cible doivent être dans le même fichier Markdown.",
    "settings.references.guide.unchanged.title": "Éléments inchangés",
    "settings.references.guide.unchanged.body": "Les liens [[#...]] ordinaires et les liens vers d’autres notes restent intacts. Une cible introuvable ou ambiguë n’est pas transformée en étiquette de renvoi, et les liens existants ne sont jamais réécrits en silence.",
    "settings.notes": "Numérotation des notes de bas de page et de fin",
