    "settings.notes.enable.desc": "Les notes de bas de page s’affichent comme 1, 2, 3 et les notes de fin comme E1, E2, E3. Chaque compteur recommence à 1 par fichier. Les définitions absentes, en double ou contradictoires restent inchangées.",
    "settings.notes.display": "Affichage dans l’aperçu direct",
