    "settings.notes.display.formatted": "Numéros formatés",
    "settings.notes.display.source": "Marqueurs d’origine",
    "settings.notes.guide.title": "Fonctionnement des notes de bas de page et de fin",
    "settings.notes.guide.intro": "Utilisez la syntaxe habituelle d’Obsidian pour les notes de bas de page et le préfixe endnote: avant l’identifiant pour les notes de fin. Chaque type a son compteur.",
