    "settings.notes.guide.safety": "La numérotation ne change que l’affichage. Les identifiants et définitions Markdown ne sont jamais réécrits.",
    "settings.noteOverrides.guide.title": "Les propriétés propres à la note sont facultatives",
    "settings.noteOverrides.guide.intro": "La plupart des notes n’ont pas besoin de propriétés Number Suite. Les réglages globaux de l’extension s’appliquent automatiquement.",
    "settings.noteOverrides.guide.action": "Ouvrez « Note actuelle » seulement si une note doit avoir d’autres réglages. « Suivre les réglages globaux » supprime la valeur particulière. Les anciens champs Number Suite ne sont convertis que lors d’une modification explicite, sans toucher aux autres propriétés.",
    "settings.missing": "Lorsque des niveaux de titres sont sautés",
    "settings.missing.desc": "Si un titre H2 est suivi directement d’un H4 sans H3, vous pouvez compléter le niveau manquant avec son numéro initial, n’afficher que le numéro H4, ou ignorer la numérotation avec un avertissement. Seule une opération de fichier distincte modifie Markdown.",
    "settings.write": "Opérations sur les fichiers",
    "settings.markers": "Écrire des marqueurs invisibles Number Suite",
    "settings.markers.desc": "Fonction expérimentale : les marqueurs invisibles permettent de reconnaître précisément les numéros écrits par l’extension, mais peuvent affecter d’autres outils et les liens vers les titres. Désactivée par défaut.",
    "settings.cleanup": "Reconnaissance initiale des numéros pour les opérations",
    "settings.cleanup.desc": "Choisissez le champ de reconnaissance initial des aperçus de suppression et de renumérotation. Vous pouvez le modifier pour chaque opération sans enregistrer ce choix dans la note.",
    "settings.multiple": "Supprimer plusieurs préfixes reconnus à la suite",
    "settings.multiple.desc": "Si plusieurs numéros reconnus se suivent au début d’un titre, ils peuvent être supprimés ensemble après vérification de l’aperçu. Les textes ambigus restent protégés.",
    "settings.normalize": "Corriger les numéros manuels fiables lors de la renumérotation",
    "settings.normalize.desc": "La renumérotation remplace aussi les préfixes manuels reconnus avec un haut niveau de confiance. Vérifiez l’aperçu avant d’appliquer.",
    "settings.operations.guide.title": "Effectuer une opération sur les fichiers",
    "settings.operations.guide.intro": "Les réglages définissent les règles. Les opérations se lancent depuis « Note actuelle » dans la barre latérale ou la palette de commandes.",
    "settings.operations.guide.step.open": "Ouvrez une note Markdown en mode Édition, puis « Note actuelle » dans Number Suite, ou exécutez la commande d’ouverture des contrôles de la note.",
    "settings.operations.guide.step.choose": "Choisissez Écrire les numéros, Supprimer les numéros, Renuméroter ou Supprimer les marqueurs Number Suite. Vous pouvez également lancer la commande propre à la note depuis la palette.",
    "settings.operations.guide.step.preview": "Comparez les changements avant/après et les avertissements, puis cliquez sur « Appliquer les modifications ». Fermer ou annuler l’aperçu n’écrit rien.",
    "settings.operations.guide.operations": "Écrire complète les numéros absents ; Supprimer efface ceux qui sont identifiés de manière fiable. Renuméroter remplace les anciens numéros reconnus par le style choisi. Supprimer les marqueurs conserve les numéros visibles.",
    "settings.operations.guide.safety": "Écrire, supprimer ou renuméroter les titres modifie leur texte et peut casser les liens ou incorporations qui les ciblent. Vérifiez l’aperçu ; l’extension ne réécrit pas ces liens automatiquement.",
    "settings.views": "Modes d’affichage",
