    "settings.references.guide.methods.copy": "Haz clic derecho sobre un título o una leyenda y elige «Copiar referencia cruzada». Se reutiliza un ID existente; si falta, puedes previsualizar y confirmar el nuevo ID antes de escribirlo.",
